param([string]$Only)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '..\..\System\Shared\Core.ps1')
. (Join-Path $PSScriptRoot '..\..\System\Shared\PDF.ps1')
$root=$script:ProjectRoot;$tokens=$null;$errors=$null
$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $PSScriptRoot 'Test-Expansion.ps1'),[ref]$tokens,[ref]$errors)
foreach($name in @('Assert','Run-Bat','HashTree','Probe','Image-Info','PDF-Count','Copy-Fixture')){$node=$ast.Find({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $name},$true);. ([scriptblock]::Create($node.Extent.Text))}
$work=Join-Path $PSScriptRoot ('_work\hundred-options-'+[guid]::NewGuid().ToString('N').Substring(0,8));Ensure-Directory $work
$fixtures=Join-Path $work 'f';Ensure-Directory $fixtures
$prior=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'hundred-phase1-results.json') -Raw -Encoding UTF8|ConvertFrom-Json
$priorFixtures=Join-Path ($prior.Sandbox.Replace('<PROJECT_ROOT>',$root)) 'f'
foreach($name in @('pages.pdf','blank.pdf','text.srt','image.png','text.txt','random.bin','video.mp4')){[IO.File]::Copy((Join-Path $priorFixtures $name),(Join-Path $fixtures $name),$false)}
$project=Join-Path $work 'اختبار عربي & ! %X% [1]';Ensure-Directory (Join-Path $project 'System');Copy-Item -LiteralPath (Join-Path $root 'System\Shared') -Destination (Join-Path $project 'System\Shared') -Recurse
Ensure-Directory (Join-Path $project 'System\Bin');Copy-Item -LiteralPath (Join-Path $root 'System\Bin\qpdf') -Destination (Join-Path $project 'System\Bin\qpdf') -Recurse
$gs=Require-Dependency ghostscript;$script:PDFEngine=$gs;$magick=Require-Dependency magick;$ff=Require-Dependency ffmpeg;$probe=Require-Dependency ffprobe;$qpdf=Require-Dependency qpdf;$script:NativeWorkingDirectory=$fixtures
$results=New-Object 'Collections.Generic.List[object]';$counter=0
function Case([string]$Name,[string]$Tool,[scriptblock]$Prepare,[string]$Answers,[scriptblock]$Verify,[string]$Arguments=''){
 if($Only -and $Name -notmatch $Only){return}
 $script:counter++;$dir=Join-Path $project ('Tools\'+$(if($Tool -like 'PDF *'){'PDF'}elseif($Tool -in @('Subtitle Tools','Video Contact Sheet')){'VID'}else{'UTI'})+'\'+$Tool)
 # Each case has a fresh project tool name directory; local scripts derive root by depth.
 $dir=Join-Path (Split-Path $dir) ($Tool+' '+$script:counter);Ensure-Directory $dir
 $category=if($Tool -like 'PDF *'){'PDF'}elseif($Tool -in @('Subtitle Tools','Video Contact Sheet')){'VID'}else{'UTI'}
 foreach($ext in @('.bat','.ps1','.md')){Copy-Item -LiteralPath (Join-Path $root ('Tools\'+$category+'\'+$Tool+'\'+$Tool+$ext)) -Destination (Join-Path $dir ($Tool+$ext))}
 $bat=Join-Path $dir ($Tool+'.bat');$inputDir=Join-Path $dir 'Input';$output=Join-Path $dir 'Output';Ensure-Directory $inputDir;Ensure-Directory $output
 try{& $Prepare;$before=HashTree $inputDir;$r=Run-Bat $bat $Arguments $Answers;$script:NativeWorkingDirectory=$fixtures;& $Verify;Assert ((HashTree $inputDir) -ceq $before) 'Input bytes changed.';$results.Add([pscustomobject]@{Test=$Name;Passed=$true;Detail='Real BAT options and content checked; originals unchanged.'});Write-Host ('PASS '+$Name)}
 catch{$results.Add([pscustomobject]@{Test=$Name;Passed=$false;Detail=$_.Exception.Message.Replace($root,'<PROJECT_ROOT>')});Write-Host ('FAIL '+$Name+': '+$_.Exception.Message)}
}
Case 'Search literal phrase and page' 'PDF Search' {Copy-Fixture 'pages.pdf' (Join-Path $inputDir 'عربي.pdf')} "2`nPAGE TWO`n" {Assert ($r.Code -eq 0) $r.Text;$rows=@(Import-Csv -LiteralPath (Join-Path $output 'search-report\matches.csv'));Assert ($rows.Count -eq 1 -and $rows[0].Page -eq 2) 'Wrong phrase page.'}
Case 'Numbers top right start7 skip1 landscape' 'PDF Add Page Numbers' {Copy-Fixture 'pages.pdf' (Join-Path $inputDir 'a.pdf')} "6`n7`n1`n" {Assert ($r.Code -eq 0) $r.Text;[void](PDF-Count (Join-Path $output 'a.pdf.numbered.pdf'));$a=Get-PDFText 'checked.pdf' 1;$b=Get-PDFText 'checked.pdf' 2;Assert ($a -notmatch '\b7\b' -and $b -match '\b7\b') 'Skip or starting number wrong.';Render-PDFPage 'checked.pdf' 2 'numbers.png' 72;$ink=(Invoke-Checked $magick @('numbers.png','-crop','80x50+320+0','-format','%[fx:minima]','info:')).Trim();Assert ([double]$ink -lt 0.2) 'Number outside top-right region.'}
Case 'Arabic watermark selected page only' 'PDF Watermark' {Copy-Fixture 'pages.pdf' (Join-Path $inputDir 'a.pdf')} "2`nنسخة للمراجعة`n2`n24`n0.5`n2`n" {Assert ($r.Code -eq 0) $r.Text;[void](PDF-Count (Join-Path $output 'a.pdf.watermarked.pdf'));Render-PDFPage 'checked.pdf' 1 'a.png' 72;Render-PDFPage 'pages.pdf' 1 'b.png' 72;$same=Invoke-Native $magick @('compare','-metric','AE','a.png','b.png','same.png');Assert ($same.Code -eq 0) 'Watermark changed excluded page.';Render-PDFPage 'checked.pdf' 2 'a2.png' 72;Render-PDFPage 'pages.pdf' 2 'b2.png' 72;$diff=Invoke-Native $magick @('compare','-metric','AE','a2.png','b2.png','arabic-watermark.png');Assert ($diff.Code -eq 1) 'Arabic mark invisible.'}
Case 'Blank removal confirmed retains faint and tiny edge marks' 'PDF Blank Page Remover' {Copy-Fixture 'blank.pdf' (Join-Path $inputDir 'a.pdf')} "2`n`nREMOVE`n" {Assert ($r.Code -eq 0) $r.Text;$path=Join-Path $output 'a.pdf.blank-review\cleaned.pdf';Assert ((PDF-Count $path) -eq 3) 'Removal deleted nonblank page.';Assert ((Get-PDFText 'checked.pdf' 1).Contains('FAINT')) 'Faint text lost.'}
Case 'Blank removal exclusion' 'PDF Blank Page Remover' {Copy-Fixture 'blank.pdf' (Join-Path $inputDir 'a.pdf')} "2`n1`nREMOVE`n" {Assert ($r.Code -eq 0 -and -not (Test-Path -LiteralPath (Join-Path $output 'a.pdf.blank-review\cleaned.pdf'))) 'Excluded page was removed.'}
Case 'Blank removal declined' 'PDF Blank Page Remover' {Copy-Fixture 'blank.pdf' (Join-Path $inputDir 'a.pdf')} "2`n`nNO`n" {Assert ($r.Code -eq 0 -and -not (Test-Path -LiteralPath (Join-Path $output 'a.pdf.blank-review\cleaned.pdf'))) 'Declined removal performed.'}
Case 'Compare unequal page counts' 'PDF Compare' {foreach($s in @('Left','Right')){Ensure-Directory (Join-Path $inputDir $s)};Copy-Fixture 'pages.pdf' (Join-Path $inputDir 'Left\a.pdf');Copy-Fixture 'blank.pdf' (Join-Path $inputDir 'Right\b.pdf')} "1`n" {Assert ($r.Code -eq 0) $r.Text;$j=Get-Content -LiteralPath (Join-Path $output 'pdf-comparison\summary.json') -Raw|ConvertFrom-Json;Assert ($j.LeftPages -eq 2 -and $j.RightPages -eq 4) 'Unequal pages not reported.';$rows=@(Import-Csv -LiteralPath (Join-Path $output 'pdf-comparison\pages.csv'));Assert (@($rows|Where-Object Visual -eq 'Missing page').Count -eq 2) 'Missing pages hidden.'}
Case 'ZIP oversized file refusal' 'Files to ZIP by Size' {[IO.File]::WriteAllBytes((Join-Path $inputDir 'big.bin'),(New-Object byte[] 1048576))} "2`n1`n" {Assert ($r.Code -ne 0 -and -not @(Get-SafeFiles $output $null -Recurse).Count) 'Oversized file not refused.'}
Case 'Date EXIF missing fallback' 'File Date Organizer' {Copy-Fixture 'image.png' (Join-Path $inputDir 'صورة.png')} "3`n" {Assert ($r.Code -eq 0) $r.Text;$row=Import-Csv -LiteralPath (Join-Path $output 'organized-dates\dates.csv');Assert ($row.DateSource -like 'Modification fallback*' -and $row.Status -eq 'Copied') 'EXIF fallback not explicit.'}
Case 'Date EXIF missing skip' 'File Date Organizer' {Copy-Fixture 'image.png' (Join-Path $inputDir 'صورة.png')} "4`n" {Assert ($r.Code -eq 0) $r.Text;$row=Import-Csv -LiteralPath (Join-Path $output 'organized-dates\dates.csv');Assert ($row.Status -eq 'Skipped' -and -not $row.Copy) 'Missing EXIF not skipped.'}
Case 'Subtitle positive shift Arabic' 'Subtitle Tools' {Copy-Fixture 'text.srt' (Join-Path $inputDir 'a.srt')} "2`n+0.500`n" {Assert ($r.Code -eq 0) $r.Text;$t=[IO.File]::ReadAllText((Join-Path $output 'a.srt.subtitles\shifted.srt'));Assert ($t.Contains('00:00:01,500 --> 00:00:02,500') -and $t.Contains('مرحبا')) 'Shift/text wrong.'}
Case 'Subtitle negative shift clamps start' 'Subtitle Tools' {Copy-Fixture 'text.srt' (Join-Path $inputDir 'a.srt')} "2`n-1.500`n" {Assert ($r.Code -eq 0) $r.Text;$t=[IO.File]::ReadAllText((Join-Path $output 'a.srt.subtitles\shifted.srt'));Assert ($t.Contains('00:00:00,000 --> 00:00:00,500') -and $t.Contains('العالم')) 'Negative shift wrong.'}
Case 'Subtitle negative shift refuses erased cue' 'Subtitle Tools' {Copy-Fixture 'text.srt' (Join-Path $inputDir 'a.srt')} "2`n-5`n" {Assert ($r.Code -ne 0 -and -not @(Get-SafeFiles $output $null -Recurse).Count) 'Erased cue not refused.'}
Case 'SRT to VTT UTF8' 'Subtitle Tools' {Copy-Fixture 'text.srt' (Join-Path $inputDir 'a.srt')} "3`n" {Assert ($r.Code -eq 0) $r.Text;$t=[IO.File]::ReadAllText((Join-Path $output 'a.srt.subtitles\converted.vtt'),(New-Object Text.UTF8Encoding($false,$true)));Assert ($t.StartsWith('WEBVTT') -and $t.Contains('00:00:01.000 --> 00:00:02.000') -and $t.Contains('مرحبا')) 'VTT conversion wrong.'}
Case 'VTT to SRT UTF8' 'Subtitle Tools' {[IO.File]::WriteAllText((Join-Path $inputDir 'a.vtt'),"WEBVTT`n`n00:01.000 --> 00:02.000`nمرحبا`n",(New-Object Text.UTF8Encoding($false)))} "4`n" {Assert ($r.Code -eq 0) $r.Text;$t=[IO.File]::ReadAllText((Join-Path $output 'a.vtt.subtitles\converted.srt'));Assert ($t.Contains('00:00:01,000 --> 00:00:02,000') -and $t.Contains('مرحبا')) 'SRT conversion wrong.'}
Case 'SRT bad end overlap and numbering report' 'Subtitle Tools' {[IO.File]::WriteAllText((Join-Path $inputDir 'a.srt'),"3`n00:00:03,000 --> 00:00:01,000`nعربي`n`n2`n00:00:00,500 --> 00:00:02,000`nTEST`n",(New-Object Text.UTF8Encoding($false)))} "1`n" {Assert ($r.Code -eq 0) $r.Text;$rows=@(Import-Csv -LiteralPath (Join-Path $output 'a.srt.subtitles\issues.csv'));Assert (@($rows|Where-Object Kind -eq 'End must follow start').Count -eq 1 -and @($rows|Where-Object Kind -eq 'Overlapping cues').Count -eq 1 -and @($rows|Where-Object Kind -eq 'Nonsequential index').Count -eq 1) 'Invalid SRT report incomplete.'}
$results.ToArray()|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $PSScriptRoot ('hundred-options'+$(if($Only){'-focused'})+'-results.json')) -Encoding UTF8
if(@($results|Where-Object{-not $_.Passed}).Count){exit 1};exit 0
